pub fn restore(
    work: &[(&str, &str)],
    historical: &[(&str, &str)],
    path: &str,
) -> Vec<(String, String)> {
    let mut tree: std::collections::BTreeMap<String, String> = work
        .iter()
        .map(|(k, v)| (k.to_string(), v.to_string()))
        .collect();
    if let Some((_, text)) = historical.iter().find(|(p, _)| *p == path)
    {
        tree.insert(path.to_owned(), text.to_string());
    } else {
        tree.remove(path);
    }
    tree.into_iter().collect()
}

fn main() {
    assert_eq!(
        restore(&[("a", "new"), ("b", "keep")], &[("a", "old")], "a"),
        vec![
            ("a".to_owned(), "old".to_owned()),
            ("b".to_owned(), "keep".to_owned())
        ],
        "case 1"
    );
    assert_eq!(restore(&[], &[], "missing"), vec![], "case 2");
    assert_eq!(restore(&[("a", "x")], &[], "a"), vec![], "case 3");
    assert_eq!(
        restore(&[], &[("a", "x")], "a"),
        vec![("a".to_owned(), "x".to_owned())],
        "case 4"
    );
    println!("worked example passed");
}

